insert into public.software (name, slug, tagline, description_short, description_full, logo_url, category_id, starting_price, price_currency, billing_period, price_is_net, price_unit, free_trial, trial_days, free_version, free_demo, pricing_plans, pricing_note, features, top_features, integrations, pros, cons, ideal_for, brand_color, gobd_compliant, datev_interface, e_invoicing, elster_submission, hosting_location, dpa_available, iso27001, tse_certified, skr_support, german_support, vendor_country, compliance_checked_at, affiliate_url, vendor_website, affiliate_network, vendor_name, founded_year, vendor_hq, support_types, countries_available, languages, editorial_rating, editorial_ease, editorial_value, editorial_service, editorial_functionality, editorial_verdict, editorial_review, editorial_author, editorial_tested_at, status, featured) values
('Sage b7', 'sage-b7', 'ERP für den Mittelstand in Handel und Produktion', 'ERP-System für mittelständische Händler und Fertiger mit komplexer Preis- und Konditionsfindung, Multichannel und Filialversorgung. Preis auf Anfrage.', '<p>Sage b7 spielt in einer anderen Liga als Sage 50. Das System richtet sich an mittelständische Handels- und Produktionsunternehmen mit vielen Artikeln, verschachtelten Konditionen und mehreren Standorten. Typische Einsatzfelder sind technischer Großhandel, Kfz-Teilehandel und Filialisten.</p><p>Die Stärke liegt in der Preis- und Konditionsfindung sowie in der Versorgung von Filialen aus mehreren Lagern. Preise nennt Sage nicht öffentlich, weil jedes Projekt mit einem Partner eingeführt wird. Interessenten erhalten ein kostenloses Infopaket und eine Beratung.</p>', null, (select id from public.categories where slug = 'erp-warenwirtschaft'), null, 'EUR', 'month', true, 'account', false, null, false, true, '[]'::jsonb, null, '["Warenwirtschaft","Einkauf und Disposition","Preis- und Konditionsfindung","Multichannel","Filialversorgung","Produktion","Zeitwirtschaft","Office-365-Integration","E-Procurement"]'::jsonb, '["Komplexe Preis- und Konditionsmodelle","Multi-Sourcing und Filialversorgung","Branchenfokus Handel und Fertigung"]'::jsonb, '["Microsoft 365","E-Procurement-Schnittstellen"]'::jsonb, '["Stark bei komplexen Handelsstrukturen","Branchenwissen im Mittelstand","Individuell erweiterbar"]'::jsonb, '["Keine öffentlichen Preise","Einführung nur als Projekt mit Partner"]'::jsonb, 'Mittelständische Händler und Fertiger mit vielen Artikeln und Standorten.', null, null, null, '[]'::jsonb, null, null, null, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.sage.com/de-de/produkte/sage-b7-warenwirtschaftssystem/', 'keins', 'Sage GmbH', null, 'Frankfurt am Main', '["Partner","Telefon"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch"]'::jsonb, 4, 3.6, 3.8, 4.1, 4.6, 'Sage b7 ist ein ERP für mittelständische Händler und Fertiger mit komplexen Preis- und Konditionsmodellen. Es wird als Projekt mit einem Partner eingeführt, Preise gibt es nur auf Anfrage.', '<h3>Einsatzfelder</h3><p>Typische Anwender sind der technische Großhandel, der Kfz-Teilehandel und Filialisten, die mehrere Standorte aus zentralen Lagern versorgen. Die Stärke liegt in Preis- und Konditionsfindung, Multi-Sourcing und Handelskalkulation.</p><h3>Funktionen</h3><p>Neben Warenwirtschaft und Disposition bietet b7 Produktion, Zeitwirtschaft, eine Integration in Microsoft 365 und E-Procurement-Schnittstellen. Das System ist individuell erweiterbar.</p><h3>Fazit</h3><p>Für Händler mit vielen tausend Artikeln und verschachtelten Konditionen ist b7 eine Option aus dem deutschen Mittelstand. Sage bietet ein kostenloses Infopaket und eine Beratung.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('Sage Sales Management', 'sage-sales-management', 'Mobiles CRM für Vertriebsteams im Außendienst', 'CRM für Vertriebsteams mit Pipeline, Zielen, Offline-App und ERP-Integration. 55 € je Nutzer im Monat, ab fünf Nutzern.', '<p>Sage Sales Management ist für Vertriebsteams gebaut, die viel unterwegs sind. Die mobile App funktioniert auch ohne Netz und kennt den Standort, Besuchsberichte lassen sich per Sprachbericht diktieren. Pipeline, Aufgaben und Teamziele laufen in einer Oberfläche zusammen.</p><p>Angeboten wird ein Tarif Professional für 55 € je Nutzer im Monat, ab fünf Nutzern. Enthalten sind bis zu 100.000 Accounts und Kontakte, die Anbindung an Microsoft 365 und Google Workspace sowie die Integration in das ERP. Sage bietet eine Demo und einen kostenlosen Test an.</p>', null, (select id from public.categories where slug = 'crm-software'), 55, 'EUR', 'month', true, 'user', true, null, false, true, '[{"name":"Professional","price":55,"period":"month","unit":"user","features":["Mindestens 5 Nutzer","Bis zu 100.000 Accounts und Kontakte","ERP-Integration","Mobile Apps, offline nutzbar","Microsoft 365 und Google Workspace"],"highlighted":true}]'::jsonb, 'mindestens 5 Nutzer', '["Pipeline","Accounts und Kontakte","Opportunities","Mobile App offline","Sprachberichte","Teamziele","E-Mail- und Kalenderintegration","ERP-Integration","Berichte und Widgets"]'::jsonb, '["Offline-fähige App für den Außendienst","Ziele für Einzelne und Teams","Integration in Microsoft 365 und Google Workspace"]'::jsonb, '["Microsoft 365","Outlook","Microsoft Teams","Google Workspace"]'::jsonb, '["Sehr gute Außendienst-App","Klare Preisangabe","Anbindung an Sage-ERP"]'::jsonb, '["Mindestens fünf Nutzer","Für sehr kleine Teams zu groß dimensioniert"]'::jsonb, 'Vertriebsteams ab fünf Personen mit viel Außendienst, besonders im Sage-Umfeld.', null, null, null, '[]'::jsonb, null, null, null, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.sage.com/de-de/produkte/sage-sales-management/', 'keins', 'Sage GmbH', null, 'Frankfurt am Main', '["Telefon","E-Mail"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch"]'::jsonb, 4.1, 4.3, 3.9, 4.1, 4.1, 'Sage Sales Management ist ein CRM für Vertriebsteams im Außendienst, mit einer Offline-App, die unterwegs zuverlässig funktioniert. Die Mindestabnahme von fünf Nutzern macht es für Kleinstteams zu groß.', '<h3>Für wen es gebaut ist</h3><p>Das CRM zielt auf Vertriebsteams, die viel beim Kunden sind. Die App arbeitet offline und mit Standortbezug, Besuchsberichte lassen sich als Sprachbericht aufnehmen. Pipeline, Aufgaben und Teamziele laufen in einer Oberfläche zusammen.</p><h3>Funktionen</h3><p>Im Tarif Professional sind bis zu 100.000 Accounts und Kontakte enthalten, dazu Opportunities, Hierarchien mit bis zu fünf Geschäftseinheiten, Berichte, Widgets und die Anbindung an Microsoft 365 und Google Workspace. Angebote, Bestellungen und Vertriebskampagnen lassen sich optional dazubuchen. Die Integration in das ERP ist vorgesehen, was es für Sage-100-Kunden besonders interessant macht.</p><h3>Preis und Test</h3><p>Professional kostet 55 € je Nutzer im Monat, ab fünf Nutzern. Sage bietet einen kostenlosen Test und eine Demo an.</p>', 'Nadeem Abbas', '2026-09-22', 'published', true),
('clockin', 'clockin', 'Zeiterfassung und Baustellendokumentation per App', 'Mobile Zeiterfassung aus Münster für Handwerk und Dienstleister mit Projektzeiten, Dokumentation und Export an die Lohnabrechnung. Ab 3,99 € je Nutzer.', '<p>clockin wurde für Betriebe entwickelt, deren Mitarbeitende selten am Schreibtisch sitzen. Gestempelt wird per App, auf Wunsch mit Projekt- und Baustellenbezug. Fotos, Notizen und Unterschriften landen direkt am Auftrag, das Büro sieht die Stunden ohne Stundenzettel.</p><p>Die Tarife beginnen bei 3,99 € je Nutzer im Monat. Für Konten mit einem bis vier Nutzern kommt eine Plattformpauschale von 10 € dazu, ab 50 Mitarbeitenden gibt es individuelle Angebote. clockin lässt sich 14 Tage kostenlos und ohne Zahlungsdaten testen und ist auch als Erweiterung für Sage Active verfügbar.</p>', null, (select id from public.categories where slug = 'zeiterfassung'), 3.99, 'EUR', 'month', true, 'user', true, 14, false, false, '[{"name":"Starter","price":3.99,"period":"month","unit":"user","features":[]},{"name":"Pro","price":6.99,"period":"month","unit":"user","features":[],"highlighted":true},{"name":"Expert","price":9.99,"period":"month","unit":"user","features":[]}]'::jsonb, 'bis 4 Nutzer zzgl. 10 € Plattformpauschale', '["Zeiterfassung per App","Projekt- und Baustellenzeiten","Dokumentation mit Fotos","Urlaubs- und Abwesenheitsverwaltung","Export an die Lohnabrechnung","Auswertungen"]'::jsonb, '["Für mobile Teams im Handwerk gebaut","Dokumentation direkt am Auftrag","Anbindung an Sage Active"]'::jsonb, '["Sage Active"]'::jsonb, '["Sehr einfache App","Günstiger Einstieg","14 Tage ohne Zahlungsdaten testbar"]'::jsonb, '["Plattformpauschale für sehr kleine Teams","Weniger Controlling-Tiefe als Projektzeit-Spezialisten"]'::jsonb, 'Handwerks- und Dienstleistungsbetriebe mit Mitarbeitenden auf Baustellen und im Außendienst.', null, null, null, '[]'::jsonb, null, null, null, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.clockin.de/', 'keins', 'clockin GmbH', null, 'Münster', '["Telefon","E-Mail","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch"]'::jsonb, 4.3, 4.6, 4.3, 4.2, 4, 'clockin aus Münster ist eine Zeiterfassung für mobile Teams im Handwerk, mit Dokumentation direkt am Auftrag. Die einfache App ist ihr stärkstes Argument.', '<h3>Für wen clockin gebaut ist</h3><p>Monteure, Handwerker und Servicetechniker stempeln per App, auf Wunsch mit Baustellen- und Projektbezug. Fotos und Notizen landen direkt am Auftrag, das Büro sieht die Stunden ohne Stundenzettel. clockin ist auch als Erweiterung für Sage Active verfügbar.</p><h3>Preise</h3><p>Starter kostet 3,99 €, Pro 6,99 € und Expert 9,99 € je Nutzer im Monat. Bei jährlicher Zahlung gibt es fünf Prozent Rabatt, bei zwei Jahren zehn Prozent. Konten mit einem bis vier Nutzern zahlen eine Plattformpauschale von 10 € im Monat. Die Testphase dauert 14 Tage, ohne Zahlungsdaten.</p><h3>Fazit</h3><p>Für Handwerks- und Servicebetriebe mit Mitarbeitenden draußen ist clockin eine der alltagstauglichsten Lösungen.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false)
